import React, { useEffect, useState } from "react";
import styles from "./MovieDetail.module.css";
import YouTube from "react-youtube";

function MovieDetail({ movieData, API_KEY, isSelected }) {
  const [videoData, setVideoData] = useState({});
  const opts = {
    height: "400",
    width: "100%",
    playerVars: {
      autoplay: 0,
    },
  };

  useEffect(() => {
    async function fetchVideo() {
      try {
        if (!movieData?.id) return;
        const response = await fetch(
          `https://api.themoviedb.org/3/movie/${movieData.id}/videos?api_key=${API_KEY}`
        );
        if (!response.ok) {
          throw new Error("failed to fetch");
        }
        const vidData = await response.json();
        setVideoData(vidData);
      } catch (err) {
        console.error(err.message);
      }
    }
    fetchVideo();
  }, [movieData, API_KEY]);

  useEffect(() => {
    console.log(videoData);
  }, [videoData]);

  return (
    <div
      className={`${styles.movieDetail} ${
        isSelected ? styles.block : styles.none
      }`}
    >
      <div>
        <h2>{movieData.title}</h2>
        <p>Release Date: {movieData.release_date}</p>
        <p>vote: {movieData.vote_average} / 10</p>
        <p>{movieData.overview}</p>
      </div>
      <div>
        <YouTube videoId={videoData?.key} opts={opts} />
      </div>
    </div>
  );
}

export default MovieDetail;
